const greetings=['no rush, really.','your thoughts can stay.','room for one more.','a soft place to land.','leave it here a while.'];let greeting=Math.floor(Math.random()*greetings.length);const message=document.getElementById('cozy-message');function showGreeting(){message.textContent=greetings[greeting]}message.onclick=()=>{greeting=(greeting+1)%greetings.length;showGreeting()};showGreeting();document.getElementById('landing-customize').onclick=()=>InnSurface.open();